<?php
namespace App\Http\Controllers;
use App\Models\{User,Product,IfcgInquiry,IfcgQuote,CrmAccount,CrmContact,CrmCampaign,CrmTask,CrmActivity,CrmOrder,CrmCase,CrmDocument,CrmTeam};
use App\Services\CrmAccess as A;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Storage};
use Illuminate\Support\Str;
use Illuminate\Validation\{Rule,ValidationException};
class CrmController extends Controller {
 private function saved(){return back()->with('success','تم الحفظ بنجاح.');}
 private function accountAccess(CrmAccount $account){A::need('accounts.read');abort_unless(A::accounts(CrmAccount::query())->whereKey($account->id)->exists(),404);}
 private function owner($id){if($id)abort_unless(A::salesOwners()->contains('id',(int)$id),422,'المسؤول خارج نطاق الفريق.');}
 private function orderQuery(){ $q=CrmOrder::with(['quote','inquiry','owner']);if(!A::can('orders.write')&&!A::can('finance.read')&&!A::can('sales.all'))$q->whereIn('inquiry_id',A::scope(IfcgInquiry::query())->select('id'));return $q; }
 public function home(){
  $tasks=A::scope(CrmTask::with('owner'))->where('status','open')->orderBy('due_at')->limit(12)->get();
  $inquiries=A::can('sales.read')?A::scope(IfcgInquiry::with('owner'))->latest()->limit(8)->get():collect();
  $orders=A::can('orders.read')?$this->orderQuery()->whereNotIn('status',['delivered','cancelled'])->orderBy('due_at')->limit(8)->get():collect();
  $stats=['متابعات مفتوحة'=>A::scope(CrmTask::query())->where('status','open')->count(),'متابعات متأخرة'=>A::scope(CrmTask::query())->where('status','open')->where('due_at','<',now())->count()];
  if(A::can('sales.read')){$stats['فرص نشطة']=A::scope(IfcgInquiry::query())->whereNotIn('status',['won','lost'])->count();$stats['عروض تنتظر الاعتماد']=IfcgQuote::whereIn('inquiry_id',A::scope(IfcgInquiry::query())->select('id'))->where('status','draft')->count();}
  if(A::can('campaigns.read')){$stats['الحملات']=CrmCampaign::count();$stats['عملاء دون مسؤول']=CrmAccount::whereNull('owner_id')->where('archived',false)->count();}
  if(A::can('orders.read'))$stats['أوامر قيد التنفيذ']=$this->orderQuery()->whereNotIn('status',['delivered','cancelled'])->count();
  return view('crm.home',compact('stats','tasks','inquiries','orders'));
 }
 public function accounts(Request $r){A::need('accounts.read');$q=A::accounts(CrmAccount::with('owner')->withCount('inquiries'));if($r->filled('q')){$term=mb_substr($r->string('q'),0,100);$q->where(fn($q)=>$q->where('name','like',"%$term%")->orWhere('email','like',"%$term%"));}if(!$r->boolean('archived'))$q->where('archived',false);return view('crm.accounts',['accounts'=>$q->latest()->paginate(20)->withQueryString(),'owners'=>A::salesOwners(),'campaigns'=>CrmCampaign::where('status','!=','archived')->get()]);}
 public function storeAccount(Request $r){A::need('accounts.write');$data=$this->accountData($r);$account=DB::transaction(function()use($data){$a=CrmAccount::create($data);A::audit('account.created',$a,$data);return $a;});return redirect()->route('crm.account',$account)->with('success','تم إنشاء ملف الشركة.');}
 private function accountData(Request $r,?CrmAccount $account=null){
  $d=$r->validate(['name'=>'required|string|max:180','email'=>'required|email|max:180','country'=>'required|string|max:100','phone'=>'nullable|string|max:40','segment'=>['required',Rule::in(array_keys(config('crm.segments')))],'source'=>['required',Rule::in(array_keys(config('crm.sources')))],'campaign_id'=>'nullable|exists:crm_campaigns,id','owner_id'=>'nullable|exists:users,id','erp_reference'=>'nullable|string|max:100','notes'=>'nullable|string|max:5000']);
  $d['email']=mb_strtolower(trim($d['email']));$d['dedupe_key']=hash('sha256',mb_strtolower(trim($d['name']).'|'.trim($d['country']).'|'.$d['email']));
  if(CrmAccount::where('dedupe_key',$d['dedupe_key'])->when($account,fn($q)=>$q->where('id','!=',$account->id))->exists())throw ValidationException::withMessages(['email'=>'الشركة بنفس الاسم والبريد والبلد موجودة بالفعل.']);
  if(A::can('sales.assign')){$this->owner($d['owner_id']??null);}else{$d['owner_id']=$account?$account->owner_id:auth()->id();}
  return $d;
 }
 public function account(CrmAccount $account){$this->accountAccess($account);$account->load(['contacts','owner']);$inquiries=A::can('sales.read')?A::scope($account->inquiries())->latest()->get():collect();return view('crm.account',compact('account','inquiries')+['owners'=>A::salesOwners(),'campaigns'=>CrmCampaign::all()]);}
 public function updateAccount(Request $r,CrmAccount $account){$this->accountAccess($account);A::need('accounts.write');$d=$this->accountData($r,$account);DB::transaction(function()use($account,$d){$old=$account->owner_id;$account->update($d);if($old!==$account->owner_id){$account->inquiries()->update(['owner_id'=>$account->owner_id]);}A::audit('account.updated',$account,$d);});return $this->saved();}
 public function archiveAccount(CrmAccount $account){$this->accountAccess($account);A::need('accounts.write');$account->update(['archived'=>!$account->archived]);A::audit('account.archived',$account,['archived'=>$account->archived]);return $this->saved();}
 public function contact(Request $r,CrmAccount $account){$this->accountAccess($account);A::need('accounts.write');$d=$r->validate(['name'=>'required|string|max:180','job_title'=>'nullable|string|max:100','email'=>'nullable|email|max:180','phone'=>'nullable|string|max:40']);$c=$account->contacts()->create($d);A::audit('contact.created',$c,$d);return $this->saved();}
 public function importAccounts(Request $r){A::need('accounts.write');$r->validate(['csv'=>'required|file|max:2048']);$handle=fopen($r->file('csv')->getRealPath(),'r');$header=fgetcsv($handle);if($header)$header[0]=ltrim($header[0],"\xEF\xBB\xBF");abort_unless($header===['name','email','country','phone','segment'],422,'الأعمدة المطلوبة: name,email,country,phone,segment');$rows=[];while(($row=fgetcsv($handle))!==false){if($row===[null])continue;abort_if(count($rows)>=500||count($row)!==5,422,'الملف بحد أقصى 500 صف وخمسة أعمدة.');$d=array_combine($header,$row);validator($d,['name'=>'required|string|max:180','email'=>'required|email|max:180','country'=>'required|string|max:100','phone'=>'nullable|string|max:40','segment'=>['required',Rule::in(array_keys(config('crm.segments')))]])->validate();$rows[]=$d;}fclose($handle);$added=0;DB::transaction(function()use($rows,&$added){foreach($rows as $d){$d['email']=mb_strtolower(trim($d['email']));$key=hash('sha256',mb_strtolower(trim($d['name']).'|'.trim($d['country']).'|'.$d['email']));if(CrmAccount::where('dedupe_key',$key)->exists())continue;$a=CrmAccount::create($d+['dedupe_key'=>$key,'source'=>'import','owner_id'=>A::can('leads.capture')?null:auth()->id()]);A::audit('account.imported',$a);$added++;}});return back()->with('success',"تم استيراد $added شركة؛ تم تجاهل السجلات المكررة دون تعديلها.");}
 public function newOpportunity(){A::need('sales.write');return view('crm.new-opportunity',['accounts'=>A::accounts(CrmAccount::query())->where('archived',false)->orderBy('name')->get(),'products'=>\App\Services\IfcgCatalog::products()]);}
 public function storeOpportunity(Request $r){A::need('sales.write');$d=$r->validate(['account_id'=>'required|exists:crm_accounts,id','contact'=>'required|string|max:180','channel'=>['required',Rule::in(['local','export','private_label'])],'expected_close'=>'nullable|date','message'=>'nullable|string|max:3000','products'=>'required|array|min:1|max:10','products.*'=>'required|integer|distinct|exists:products,id','quantity'=>'required|numeric|min:0.001|max:1000000']);$a=CrmAccount::findOrFail($d['account_id']);$this->accountAccess($a);abort_if($a->archived,422);$items=[];foreach($d['products'] as $id){$p=Product::active()->where('sku','like','IFCG-DEMO-%')->findOrFail($id);$items[]=['product_id'=>$p->id,'name'=>$p->name,'quantity'=>$d['quantity'],'unit'=>'kg'];}$i=IfcgInquiry::create(['reference'=>'RFQ-'.strtoupper(Str::random(10)),'account_id'=>$a->id,'company'=>$a->name,'contact'=>$d['contact'],'email'=>$a->email,'phone'=>$a->phone,'country'=>$a->country,'channel'=>$d['channel'],'locale'=>app()->getLocale(),'items'=>$items,'owner_id'=>$a->owner_id?:auth()->id(),'status'=>'new','source'=>$a->source,'campaign_id'=>$a->campaign_id,'expected_close'=>$d['expected_close']??null,'message'=>$d['message']??null]);A::audit('opportunity.created',$i);return redirect()->route('ifcg.inquiry',$i);}
 public function tasks(){return view('crm.tasks',['tasks'=>A::scope(CrmTask::with(['owner','inquiry']))->orderBy('status')->orderBy('due_at')->paginate(25),'owners'=>A::can('tasks.assign')?A::salesOwners():User::whereKey(auth()->id())->get(),'inquiries'=>A::can('sales.read')?A::scope(IfcgInquiry::query())->latest()->limit(200)->get():collect()]);}
 public function storeTask(Request $r){$d=$r->validate(['title'=>'required|string|max:180','owner_id'=>'required|exists:users,id','inquiry_id'=>'nullable|exists:ifcg_inquiries,id','due_at'=>'required|date','priority'=>['required',Rule::in(['normal','high'])],'notes'=>'nullable|string|max:3000']);if(!A::can('tasks.assign'))$d['owner_id']=auth()->id();else $this->owner($d['owner_id']);if(!empty($d['inquiry_id'])){A::inquiry(IfcgInquiry::findOrFail($d['inquiry_id']));$target=User::findOrFail($d['owner_id']);$i=IfcgInquiry::findOrFail($d['inquiry_id']);abort_unless($target->id===$i->owner_id||$target->hasRole('admin')||($target->hasRole('sales_manager')&&$target->crm_team_id&&$target->crm_team_id===User::find($i->owner_id)?->crm_team_id),422,'المهمة مرتبطة بفرصة لا يملك الموظف صلاحية مشاهدتها.');}$task=CrmTask::create($d);A::audit('task.created',$task,$d);return $this->saved();}
 public function updateTask(Request $r,CrmTask $task){abort_unless(A::scope(CrmTask::query())->whereKey($task->id)->exists(),404);$d=$r->validate(['status'=>['required',Rule::in(['open','done'])]]);$task->update($d);A::audit('task.updated',$task,$d);return $this->saved();}
 public function activity(Request $r,IfcgInquiry $inquiry){A::inquiry($inquiry);A::need('sales.write');$d=$r->validate(['kind'=>['required',Rule::in(['call','meeting','email','whatsapp','note'])],'body'=>'required|string|max:5000']);$activity=CrmActivity::create($d+['inquiry_id'=>$inquiry->id,'user_id'=>auth()->id()]);A::audit('activity.created',$activity);return $this->saved();}
 public function campaigns(){A::need('campaigns.read');$campaigns=CrmCampaign::latest()->get();foreach($campaigns as $c){$c->leads=IfcgInquiry::where('campaign_id',$c->id)->count();$c->qualified=IfcgInquiry::where('campaign_id',$c->id)->whereNotIn('status',['new','lost'])->count();$c->won=IfcgInquiry::where('campaign_id',$c->id)->where('status','won')->count();}return view('crm.campaigns',compact('campaigns'));}
 public function saveCampaign(Request $r,?CrmCampaign $campaign=null){A::need('campaigns.write');$d=$r->validate(['name'=>'required|string|max:180','code'=>['required','alpha_dash','max:80',Rule::unique('crm_campaigns')->ignore($campaign?->id)],'channel'=>['required',Rule::in(array_keys(config('crm.sources')))],'status'=>['required',Rule::in(['draft','active','completed','archived'])],'currency'=>['required',Rule::in(config('crm.currencies'))],'spend'=>'required|numeric|min:0|max:100000000|regex:/^\d+(\.\d{1,2})?$/','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after_or_equal:starts_at','notes'=>'nullable|string|max:3000']);$d['spend_minor']=(int)round($d['spend']*100);unset($d['spend']);$campaign=$campaign?:new CrmCampaign;$campaign->fill($d)->save();A::audit('campaign.saved',$campaign,$d);return $this->saved();}
 public function orders(){A::need('orders.read');return view('crm.orders',['orders'=>$this->orderQuery()->latest()->paginate(25)]);}
 public function convert(IfcgQuote $quote){A::inquiry($quote->inquiry);A::need('sales.write');$order=DB::transaction(function()use($quote){$q=IfcgQuote::lockForUpdate()->findOrFail($quote->id);abort_unless($q->status==='accepted',422,'يجب تسجيل قبول العميل أولًا.');$existing=CrmOrder::where('inquiry_id',$q->inquiry_id)->first();if($existing){abort_unless($existing->quote_id===$q->id,422,'هذه الفرصة مرتبطة بأمر بيع آخر.');return $existing;}$order=CrmOrder::create(['reference'=>'SO-'.strtoupper(Str::random(10)),'quote_id'=>$q->id,'inquiry_id'=>$q->inquiry_id]);A::audit('order.created',$order,['quote'=>$q->reference]);return $order;});return redirect()->route('crm.order',$order);}
 public function order(CrmOrder $order){A::order($order);$order->load(['quote','inquiry','owner']);$docs=CrmDocument::where('inquiry_id',$order->inquiry_id);if(!A::can('finance.read'))$docs->where('visibility','operations');return view('crm.order',compact('order')+['owners'=>User::whereHas('roles',fn($q)=>$q->whereIn('name',['admin','operations']))->where('is_active',true)->get(),'documents'=>$docs->get()]);}
 public function updateOrder(Request $r,CrmOrder $order){A::order($order);A::need('orders.write');$d=$r->validate(['status'=>['required',Rule::in(array_keys(config('crm.order_states')))],'owner_id'=>'nullable|exists:users,id','due_at'=>'nullable|date','erp_reference'=>'nullable|string|max:100','availability'=>['required',Rule::in(['unconfirmed','available','production'])],'availability_reference'=>'nullable|string|max:1000','tracking'=>'nullable|string|max:180','delivery_proof'=>'nullable|string|max:2000','notes'=>'nullable|string|max:4000']);if(!empty($d['owner_id']))abort_unless(User::whereHas('roles',fn($q)=>$q->whereIn('name',['admin','operations']))->where('is_active',true)->whereKey($d['owner_id'])->exists(),422);DB::transaction(function()use($order,$d){$o=CrmOrder::lockForUpdate()->findOrFail($order->id);$allowed=['pending'=>['pending','preparing','cancelled'],'preparing'=>['preparing','ready','cancelled'],'ready'=>['ready','shipped','cancelled'],'shipped'=>['shipped','delivered'],'delivered'=>['delivered'],'cancelled'=>['cancelled']];abort_unless(in_array($d['status'],$allowed[$o->status]),422,'الانتقال بين مراحل التنفيذ غير مسموح.');if(in_array($d['status'],['ready','shipped','delivered']))abort_unless($d['availability']==='available'&&!empty($d['availability_reference']),422,'سجّل تأكيد الإتاحة ومرجعه من برنامج الشركة.');if($d['status']==='shipped')abort_unless(in_array($o->payment_status,['cleared','credit_approved'])&&!empty($d['tracking'])&&!empty($d['erp_reference']),422,'الشحن يحتاج موافقة مالية ورقم شحنة ومرجع أمر البيع الخارجي.');if($d['status']==='delivered')abort_if(empty($d['delivery_proof']),422,'أدخل إثبات التسليم.');$o->update($d);A::audit('order.updated',$o,$d);});return $this->saved();}
 public function finance(Request $r,CrmOrder $order){A::order($order);A::need('finance.write');$d=$r->validate(['payment_status'=>['required',Rule::in(['unconfirmed','pending','cleared','credit_approved'])],'payment_reference'=>'required|string|max:2000','collected'=>'required|numeric|min:0|regex:/^\d+(\.\d{1,2})?$/','payment_due_at'=>'nullable|date']);$d['collected_minor']=(int)round($d['collected']*100);unset($d['collected']);abort_if($d['collected_minor']>$order->quote->total_minor,422,'المبلغ المحصل يتجاوز قيمة الأمر.');abort_if($d['payment_status']==='cleared'&&$d['collected_minor']<$order->quote->total_minor,422,'السداد الكامل يحتاج مبلغًا يغطي الأمر. استخدم اعتماد الآجل عند وجود اتفاق معتمد.');abort_if($d['payment_status']==='credit_approved'&&empty($d['payment_due_at']),422,'حدد موعد استحقاق الآجل.');DB::transaction(function()use($order,$d){$order->update($d);A::audit('finance.confirmed',$order,$d);});return $this->saved();}
 public function cases(){abort_unless(A::can('sales.read')||A::can('cases.write'),403);$q=CrmCase::with('inquiry');if(!A::can('cases.write'))$q->whereIn('inquiry_id',A::scope(IfcgInquiry::query())->select('id'));return view('crm.cases',['cases'=>$q->latest()->paginate(25),'inquiries'=>A::can('cases.write')?IfcgInquiry::whereIn('id',CrmOrder::select('inquiry_id'))->get():A::scope(IfcgInquiry::query())->latest()->limit(200)->get()]);}
 public function storeCase(Request $r){abort_unless(A::can('sales.write')||A::can('cases.write'),403);$d=$r->validate(['inquiry_id'=>'required|exists:ifcg_inquiries,id','kind'=>['required',Rule::in(['sample','complaint','return'])],'title'=>'required|string|max:180','due_at'=>'nullable|date']);if(!A::can('cases.write'))A::inquiry(IfcgInquiry::findOrFail($d['inquiry_id']));else abort_unless(CrmOrder::where('inquiry_id',$d['inquiry_id'])->exists(),422);$c=CrmCase::create($d+['owner_id'=>auth()->id()]);A::audit('case.created',$c,$d);return $this->saved();}
 public function updateCase(Request $r,CrmCase $case){if(!A::can('cases.write')){A::inquiry($case->inquiry);A::need('sales.write');}$d=$r->validate(['status'=>['required',Rule::in(['open','in_progress','closed'])],'resolution'=>'required|string|max:3000']);$case->update($d);A::audit('case.updated',$case,$d);return $this->saved();}
 public function upload(Request $r,IfcgInquiry $inquiry){$d=$r->validate(['document'=>'required|file|mimes:pdf,jpg,jpeg,png,webp,docx,xlsx|max:10240','visibility'=>['required',Rule::in(['sales','operations','finance'])]]);$this->documentAccess($inquiry,$d['visibility'],true);$file=$r->file('document');$path=$file->store('crm-private','local');$doc=CrmDocument::create(['inquiry_id'=>$inquiry->id,'user_id'=>auth()->id(),'name'=>mb_substr(basename($file->getClientOriginalName()),0,180),'path'=>$path,'visibility'=>$d['visibility']]);A::audit('document.uploaded',$doc,['name'=>$doc->name,'visibility'=>$doc->visibility]);return $this->saved();}
 private function documentAccess($inquiry,$visibility,$write=false){if($visibility==='sales'){A::inquiry($inquiry);if($write)A::need('sales.write');}else{$o=CrmOrder::where('inquiry_id',$inquiry->id)->firstOrFail();A::order($o);A::need($visibility==='finance'?($write?'finance.write':'finance.read'):($write?'orders.write':'orders.read'));}}
 public function download(CrmDocument $document){$this->documentAccess(IfcgInquiry::findOrFail($document->inquiry_id),$document->visibility);abort_unless(Storage::disk('local')->exists($document->path),404);return Storage::disk('local')->download($document->path,$document->name,['X-Content-Type-Options'=>'nosniff']);}
 public function users(){A::need('users');return view('crm.users',['users'=>User::whereHas('roles',fn($q)=>$q->whereIn('name',array_keys(config('crm.roles'))))->with('roles')->get(),'teams'=>CrmTeam::all()]);}
 public function team(Request $r){A::need('users');$d=$r->validate(['name'=>'required|string|max:100|unique:crm_teams']);$t=CrmTeam::create($d);A::audit('team.created',$t,$d);return $this->saved();}
 public function saveUser(Request $r,?User $user=null){A::need('users');$roles=array_keys(config('crm.roles'));if(!auth()->user()->hasRole('admin'))$roles=array_values(array_diff($roles,['admin','system_admin','executive']));$d=$r->validate(['name'=>'required|string|max:180','email'=>['required','email','max:180',Rule::unique('users')->ignore($user?->id)],'password'=>[$user?'nullable':'required','string','min:12','max:128','confirmed'],'role'=>['required',Rule::in($roles)],'crm_team_id'=>'nullable|exists:crm_teams,id','is_active'=>'required|boolean']);if($user){abort_if($user->id===auth()->id()&&(!$r->boolean('is_active')||!$user->hasRole($d['role'])),422,'لا يمكنك تعطيل حسابك أو تغيير دورك بنفسك.');if(!auth()->user()->hasRole('admin'))abort_if($user->hasAnyRole(['admin','system_admin','executive']),403);if($user->hasRole('admin')&&(!$r->boolean('is_active')||$d['role']!=='admin'))abort_if(User::whereHas('roles',fn($q)=>$q->where('name','admin'))->where('is_active',true)->where('id','!=',$user->id)->count()===0,422,'يجب الإبقاء على مدير رئيسي نشط.');}
  DB::transaction(function()use($d,$user){$u=$user?:new User;$u->name=$d['name'];$u->email=$d['email'];$u->is_active=(bool)$d['is_active'];$u->crm_team_id=$d['crm_team_id']??null;if(!empty($d['password']))$u->password=Hash::make($d['password']);$u->session_version=($u->session_version?:0)+1;$u->save();\Spatie\Permission\Models\Role::firstOrCreate(['name'=>$d['role'],'guard_name'=>'web']);$u->syncRoles([$d['role']]);A::audit('user.saved',$u,['role'=>$d['role'],'active'=>$u->is_active,'team'=>$u->crm_team_id]);if($u->id===auth()->id())session(['crm_session_version_'.$u->id=>$u->session_version]);});return $this->saved();
 }
 public function reports(){A::need('reports');$q=A::can('sales.read')?A::scope(IfcgInquiry::query()):IfcgInquiry::query();$stages=(clone $q)->select('status',DB::raw('count(*) as total'))->groupBy('status')->pluck('total','status');$sources=(clone $q)->select('source',DB::raw('count(*) as total'))->groupBy('source')->get();$losses=(clone $q)->where('status','lost')->select('loss_reason',DB::raw('count(*) as total'))->groupBy('loss_reason')->get();$totals=A::can('sales.read')?IfcgQuote::whereIn('inquiry_id',(clone $q)->select('id'))->where('status','accepted')->select('currency',DB::raw('sum(total_minor) as total'))->groupBy('currency')->get():collect();return view('crm.reports',compact('stages','sources','losses','totals'));}
 public function audit(){A::need('audit');return view('crm.audit',['events'=>DB::table('crm_audits')->leftJoin('users','users.id','=','crm_audits.user_id')->select('crm_audits.*','users.name as actor')->orderByDesc('crm_audits.id')->paginate(40)]);}
}
